let currentLanguage = 'en';
let blockedLanguages = [];
let searchCache = [];

class EnhancedSearch {
    constructor() {
        this.searchIndex = new Map();
        this.fuse = null;
        this.isIndexed = false;
        this.searchCache = new Map();
        this.debounceTimer = null;
    }

    async initialize() {
        await this.buildSearchIndex();
        this.initializeFuzzySearch();
        console.log('Enhanced search system initialized');
    }

    async buildSearchIndex() {
        try {
            const response = await sendMessageToYouTube({ type: "getBlockedVideos" });
            const blockedVideos = response?.blockedVideosMap || {};
            this.searchIndex.clear();
            Object.values(blockedVideos).forEach((video, index) => {
                const searchableText = this.normalizeText(
                    `${video.title} ${video.id} ${video.reason} ${video.timestamp}`
                );
                this.searchIndex.set(index, {
                    id: video.id,
                    title: video.title,
                    videoId: video.id,
                    reason: video.reason,
                    timestamp: video.timestamp,
                    ts: video.ts,
                    searchableText: searchableText,
                    originalData: video,
                    matchingKeywords: video.matchingKeywords || [],
                    keywordCount: video.keywordCount || 0
                });
            });
            this.isIndexed = true;
            console.log(`Search index built with ${this.searchIndex.size} items`);
        } catch (error) {
            console.error('Error building search index:', error);
        }
    }

    initializeFuzzySearch() {
        this.fuse = {
            search: (query, items, options = {}) => {
                const normalizedQuery = this.normalizeText(query);
                if (!normalizedQuery) return items;
                const results = [];
                const threshold = options.threshold || 0.3;
                items.forEach((item, index) => {
                    const score = this.calculateSimilarity(normalizedQuery, item.searchableText);
                    if (score >= threshold) {
                        results.push({ item, score, index });
                    }
                });
                return results.sort((a, b) => b.score - a.score).map(r => r.item);
            }
        };
    }

    normalizeText(text) {
        return text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^\w\s]/g, ' ').replace(/\s+/g, ' ').trim();
    }

    calculateSimilarity(query, text) {
        if (query === text) return 1.0;
        if (text.includes(query)) return 0.8;
        const queryWords = query.split(' ');
        const textWords = text.split(' ');
        let matches = 0;
        queryWords.forEach(qWord => {
            if (textWords.some(tWord => tWord.includes(qWord) || qWord.includes(tWord))) matches++;
        });
        return matches / queryWords.length;
    }

    search(query, filters = {}) {
        if (!this.isIndexed || !query.trim()) return this.getAllVideos(filters);
        const cacheKey = `${query}-${JSON.stringify(filters)}`;
        if (this.searchCache.has(cacheKey)) return this.searchCache.get(cacheKey);
        const normalizedQuery = this.normalizeText(query);
        const allItems = Array.from(this.searchIndex.values());
        let filteredItems = this.applyFilters(allItems, filters);
        let results = this.fuse.search(normalizedQuery, filteredItems);
        if (results.length === 0) results = this.partialMatchSearch(normalizedQuery, filteredItems);
        results = this.sortResults(results, filters.sortBy || 'newest');
        this.searchCache.set(cacheKey, results);
        return results;
    }

    applyFilters(items, filters) {
        let filtered = items;
        if (filters.reason && filters.reason !== 'all') filtered = filtered.filter(item => item.reason === filters.reason);
        if (filters.dateRange && filters.dateRange !== 'all') filtered = this.filterByDateRange(filtered, filters.dateRange);
        return filtered;
    }

    filterByDateRange(items, dateRange) {
        const now = Date.now();
        const ranges = { 'today': 86400000, 'week': 604800000, 'month': 2592000000, 'year': 31536000000 };
        if (ranges[dateRange]) { const cutoff = now - ranges[dateRange]; return items.filter(item => item.ts >= cutoff); }
        return items;
    }

    partialMatchSearch(query, items) {
        const queryWords = query.split(' ');
        return items.filter(item => queryWords.some(word => item.searchableText.includes(word) || item.title.toLowerCase().includes(word) || item.videoId.includes(word) || item.reason.includes(word)));
    }

    sortResults(items, sortBy) {
        const sorted = [...items];
        switch (sortBy) {
            case 'newest': return sorted.sort((a, b) => b.ts - a.ts);
            case 'oldest': return sorted.sort((a, b) => a.ts - b.ts);
            case 'title': return sorted.sort((a, b) => a.title.localeCompare(b.title));
            default: return sorted;
        }
    }

    getAllVideos(filters = {}) {
        const allItems = Array.from(this.searchIndex.values());
        const filtered = this.applyFilters(allItems, filters);
        return this.sortResults(filtered, filters.sortBy || 'newest');
    }

    async refreshIndex() {
        this.searchCache.clear();
        await this.buildSearchIndex();
    }

    getSearchSuggestions(query) {
        if (!query.trim() || !this.isIndexed) return [];
        const normalizedQuery = this.normalizeText(query);
        const allItems = Array.from(this.searchIndex.values());
        const suggestions = new Set();
        allItems.forEach(item => {
            if (item.title.toLowerCase().includes(normalizedQuery)) suggestions.add(item.title.substring(0, 50));
            if (item.reason.toLowerCase().includes(normalizedQuery)) suggestions.add(item.reason);
            if (item.videoId.includes(normalizedQuery)) suggestions.add(item.videoId);
        });
        return Array.from(suggestions).slice(0, 5);
    }
}

const enhancedSearch = new EnhancedSearch();

class StatsManager {
    constructor() {
        this.stats = { totalBlocks: 0, todayBlocks: 0, manualBlocks: 0, keywordBlocks: 0, shortsBlocks: 0, languageBlocks: 0, channelBlocks: 0, activeKeywords: 0, sponsorBlockSkips: 0, sponsorBlockTimeSaved: 0, dailyActivity: {}, lastUpdated: null };
    }

    async loadStats() {
        try {
            const statsResponse = await sendMessageToYouTube({ type: "getStats" });
            if (statsResponse && statsResponse.success !== false) {
                this.stats = this.mergeStats(this.stats, statsResponse);
            } else {
                await this.loadFromLocalStorage();
            }
            this.stats.lastUpdated = new Date().toISOString();
            return this.stats;
        } catch (error) {
            console.error('Clify: Error loading stats:', error);
            await this.loadFromLocalStorage();
            return this.stats;
        }
    }

    async loadFromLocalStorage() {
        return new Promise((resolve) => {
            chrome.storage.local.get(['ClifyStats', 'blockedVideos', 'keywords'], (result) => {
                const blockedVideos = result.blockedVideos || {};
                const storedStats = result.ClifyStats || {};
                const keywords = result.keywords || [];
                const videoArray = Object.values(blockedVideos);
                const today = new Date().toISOString().slice(0, 10);
                this.stats = {
                    totalBlocks: videoArray.length,
                    todayBlocks: videoArray.filter(v => new Date(v.ts).toISOString().slice(0, 10) === today).length,
                    manualBlocks: videoArray.filter(v => v.reason === 'manual').length,
                    keywordBlocks: videoArray.filter(v => v.reason === 'keyword').length,
                    shortsBlocks: videoArray.filter(v => v.reason === 'shorts').length,
                    languageBlocks: videoArray.filter(v => v.reason === 'language').length,
                    activeKeywords: keywords.length,
                    dailyActivity: storedStats.dailyActivity || this.generateEmptyActivityChart(),
                    lastUpdated: new Date().toISOString()
                };
                resolve(this.stats);
            });
        });
    }

    mergeStats(existing, newStats) {
        return {
            totalBlocks: newStats.totalBlocks || existing.totalBlocks,
            todayBlocks: newStats.todayBlocks || existing.todayBlocks,
            manualBlocks: newStats.manualBlocks || existing.manualBlocks,
            keywordBlocks: newStats.keywordBlocks || existing.keywordBlocks,
            shortsBlocks: newStats.shortsBlocks || existing.shortsBlocks,
            languageBlocks: newStats.languageBlocks || existing.languageBlocks,
            channelBlocks: newStats.channelBlocks || existing.channelBlocks,
            activeKeywords: newStats.activeKeywords || existing.activeKeywords,
            sponsorBlockSkips: newStats.sponsorBlockSkips || existing.sponsorBlockSkips,
            sponsorBlockTimeSaved: newStats.sponsorBlockTimeSaved || existing.sponsorBlockTimeSaved,
            dailyActivity: newStats.dailyActivity || existing.dailyActivity,
            lastUpdated: new Date().toISOString()
        };
    }

    generateEmptyActivityChart() {
        const activity = {};
        for (let i = 29; i >= 0; i--) { const date = new Date(); date.setDate(date.getDate() - i); activity[date.toISOString().slice(0, 10)] = 0; }
        return activity;
    }

    getStats() { return this.stats; }

    calculateEfficiency() {
        if (this.stats.totalBlocks === 0) return 0;
        const activeDays = Object.values(this.stats.dailyActivity).filter(count => count > 0).length;
        return Math.min(100, Math.round((this.stats.totalBlocks / Math.max(1, activeDays)) * 10));
    }
}

const statsManager = new StatsManager();

class YouTubeIntegration {
    constructor() { this.isConnected = false; }

    async sendMessageToContentScript(message) {
        try {
            const tabs = await new Promise((resolve, reject) => {
                chrome.tabs.query({ url: "*://*.youtube.com/*" }, (result) => {
                    if (chrome.runtime.lastError) reject(new Error(chrome.runtime.lastError.message));
                    else resolve(result || []);
                });
            });
            if (tabs.length === 0) return this.handleFallbackStorage(message);
            const activeTab = tabs.find(tab => tab.active);
            const targetTab = activeTab || tabs[0];
            return new Promise((resolve) => {
                chrome.tabs.sendMessage(targetTab.id, message, (response) => {
                    if (chrome.runtime.lastError) {
                        this.isConnected = false;
                        resolve(this.handleFallbackStorage(message));
                    } else {
                        this.isConnected = true;
                        resolve(response);
                    }
                });
            });
        } catch (error) {
            return this.handleFallbackStorage(message);
        }
    }

    async handleFallbackStorage(message) {
        return new Promise((resolve) => {
            chrome.storage.local.get(['blockedVideos', 'keywords', 'ClifyStats'], (result) => {
                const blockedVideos = result.blockedVideos || {};
                const videoArray = Object.values(blockedVideos);
                const today = new Date().toISOString().slice(0, 10);
                switch (message.type) {
                    case "getStats":
                        resolve({
                            totalBlocks: videoArray.length,
                            todayBlocks: videoArray.filter(v => new Date(v.ts).toISOString().slice(0, 10) === today).length,
                            manualBlocks: videoArray.filter(v => v.reason === 'manual').length,
                            keywordBlocks: videoArray.filter(v => v.reason === 'keyword').length,
                            shortsBlocks: videoArray.filter(v => v.reason === 'shorts').length,
                            languageBlocks: videoArray.filter(v => v.reason === 'language').length,
                            activeKeywords: (result.keywords || []).length,
                            dailyActivity: result.ClifyStats?.dailyActivity || {},
                            success: true
                        });
                        break;
                    case "getBlockedVideos": resolve({ blockedVideosMap: blockedVideos, success: true }); break;
                    case "getKeywords": chrome.storage.sync.get({ keywords: [] }, (sr) => resolve({ keywords: sr.keywords, success: true })); break;
                    case "saveKeywords": chrome.storage.sync.set({ keywords: message.keywords }, () => resolve({ success: true })); break;
                    case "clearAllVideos": chrome.storage.local.set({ blockedVideos: {} }, () => chrome.storage.sync.set({ keywords: [] }, () => resolve({ success: true }))); break;
                    case "unblockVideo": delete blockedVideos[message.videoId]; chrome.storage.local.set({ blockedVideos }, () => resolve({ success: true })); break;
                    case "incrementAdsBlocked": {
                        chrome.storage.local.get(['clify_data'], (r) => {
                            const d = r.clify_data || { stats: {} };
                            if (!d.stats) d.stats = {};
                            d.stats.adsBlocked = (d.stats.adsBlocked || 0) + (message.count || 1);
                            chrome.storage.local.set({ clify_data: d }, () => resolve({ success: true }));
                        });
                        break;
                    }
                    case "incrementBannersRemoved": {
                        chrome.storage.local.get(['clify_data'], (r) => {
                            const d = r.clify_data || { stats: {} };
                            if (!d.stats) d.stats = {};
                            d.stats.bannersRemoved = (d.stats.bannersRemoved || 0) + (message.count || 1);
                            chrome.storage.local.set({ clify_data: d }, () => resolve({ success: true }));
                        });
                        break;
                    }
                    case "incrementSkipped": {
                        chrome.storage.local.get(['clify_data'], (r) => {
                            const d = r.clify_data || { stats: {} };
                            if (!d.stats) d.stats = {};
                            d.stats.skipped = (d.stats.skipped || 0) + (message.count || 1);
                            chrome.storage.local.set({ clify_data: d }, () => resolve({ success: true }));
                        });
                        break;
                    }
                    case "toggleAdBlocker": chrome.storage.local.set({ adBlockerConfig: message.config }, () => resolve({ success: true })); break;
                    case "getAdBlockerStatus": {
                        chrome.storage.local.get(['adBlockerConfig', 'adBlockerStats', 'clify_data', 'blockedVideos'], (r) => {
                            const clifyData = r.clify_data || {};
                            const stats = clifyData.stats || {};
                            resolve({ config: r.adBlockerConfig || {}, stats: { totalBlocked: stats.adsBlocked || 0, bannersRemoved: stats.bannersRemoved || 0, skipped: stats.skipped || 0 }, success: true, ruleCount: 0 });
                        });
                        break;
                    }
                    case "blockChannel": {
                        chrome.storage.local.get(['clify_blocked_channels'], (r) => {
                            const ch = r.clify_blocked_channels || {};
                            const channelData = message.channelData || { id: message.name, name: message.name, url: message.url || '', ts: Date.now() };
                            ch[channelData.id] = channelData;
                            chrome.storage.local.set({ clify_blocked_channels: ch }, () => resolve({ success: true }));
                        });
                        break;
                    }
                    case "unblockChannel": {
                        chrome.storage.local.get(['clify_blocked_channels'], (r) => {
                            const ch = r.clify_blocked_channels || {};
                            const key = message.channelId || message.name;
                            delete ch[key];
                            chrome.storage.local.set({ clify_blocked_channels: ch }, () => resolve({ success: true }));
                        });
                        break;
                    }
                    case "getBlockedChannels": chrome.storage.local.get(['clify_blocked_channels'], (r) => resolve({ channels: r.clify_blocked_channels || {}, success: true })); break;
                    case "whitelistChannel": {
                        chrome.storage.local.get(['clify_whitelisted_channels'], (r) => {
                            const wl = r.clify_whitelisted_channels || {};
                            const channelData = message.channelData || { id: message.name, name: message.name, url: message.url || '', ts: Date.now() };
                            wl[channelData.id] = channelData;
                            chrome.storage.local.set({ clify_whitelisted_channels: wl }, () => resolve({ success: true }));
                        });
                        break;
                    }
                    case "unwhitelistChannel": {
                        chrome.storage.local.get(['clify_whitelisted_channels'], (r) => {
                            const wl = r.clify_whitelisted_channels || {};
                            const key = message.channelId || message.name;
                            delete wl[key];
                            chrome.storage.local.set({ clify_whitelisted_channels: wl }, () => resolve({ success: true }));
                        });
                        break;
                    }
                    case "getWhitelistedChannels": chrome.storage.local.get(['clify_whitelisted_channels'], (r) => resolve({ channels: r.clify_whitelisted_channels || {}, success: true })); break;
                    case "clearAllChannels": chrome.storage.local.set({ clify_blocked_channels: {}, clify_whitelisted_channels: {} }, () => resolve({ success: true })); break;
                    case "setPreferredLanguages": {
                        chrome.storage.local.set({ clify_language_config: { languageBlock: message.languageBlock, preferredLanguages: message.languages } }, () => resolve({ success: true }));
                        break;
                    }
                    case "toggleLanguageBlock": {
                        chrome.storage.local.set({ clify_language_config: { languageBlock: message.enabled } }, () => resolve({ success: true }));
                        break;
                    }
                    case "getEnhancedConfig": chrome.storage.sync.get(['clify_config'], (r) => resolve({ config: r.clify_config || {}, success: true })); break;
                    case "saveEnhancedConfig": chrome.storage.sync.set({ clify_config: message.config }, () => resolve({ success: true })); break;
                    case "toggleShortsRemoval": {
                        chrome.storage.sync.get(['clify_config'], (r) => {
                            const cfg = r.clify_config || {};
                            cfg.shortsRemoval = message.enabled !== false;
                            chrome.storage.sync.set({ clify_config: cfg }, () => resolve({ success: true }));
                        });
                        break;
                    }
                    case "toggleBlurMode": {
                        chrome.storage.sync.get(['clify_config'], (r) => {
                            const cfg = r.clify_config || {};
                            cfg.blurMode = message.enabled === true;
                            chrome.storage.sync.set({ clify_config: cfg }, () => resolve({ success: true }));
                        });
                        break;
                    }
                    default: resolve({ success: false, error: 'Unknown message type' });
                }
            });
        });
    }
}

const youTubeIntegration = new YouTubeIntegration();

async function sendMessageToYouTube(message) {
    return youTubeIntegration.sendMessageToContentScript(message);
}

function $(selector, context) {
    context = context || document;
    try { const el = context.querySelector(selector); return el; } catch (e) { return null; }
}

function $$(selector, context) {
    context = context || document;
    try { return Array.from(context.querySelectorAll(selector)); } catch (e) { return []; }
}

function safeElement(selector, callback) {
    const element = $(selector);
    if (element && callback) callback(element);
    return element;
}

function initNotificationSystem() {
    let container = $('#notificationContainer');
    if (!container) { container = document.createElement('div'); container.id = 'notificationContainer'; container.className = 'notification-container'; document.body.appendChild(container); }
    return container;
}

function showNotification(message, type = "success", options = {}) {
    const container = initNotificationSystem();
    const notification = document.createElement('div');
    notification.className = `notification ${type}`;
    notification.innerHTML = `
        <div class="notification-content">
            <div class="notification-icon"><i class="${getNotificationIcon(type)}"></i></div>
            <div class="notification-text">
                <div class="notification-title">${options.title || getDefaultTitle(type)}</div>
                <div class="notification-message">${message}</div>
            </div>
            <button class="notification-close" aria-label="Close notification"><i class="ti ti-x"></i></button>
        </div>
        <div class="notification-progress"></div>`;
    container.appendChild(notification);
    setTimeout(() => notification.classList.add('show'), 10);
    notification.querySelector('.notification-close').addEventListener('click', () => hideNotification(notification));
    const progressBar = notification.querySelector('.notification-progress');
    progressBar.style.animation = `notificationProgress ${options.duration || 4000}ms linear forwards`;
    setTimeout(() => { if (notification.parentNode) hideNotification(notification); }, options.duration || 4000);
    return notification;
}

function hideNotification(notification) {
    notification.classList.remove('show');
    notification.classList.add('hiding');
    setTimeout(() => { if (notification.parentNode) notification.parentNode.removeChild(notification); }, 400);
}

function getDefaultTitle(type) { return { success: 'Done!', error: 'Error', warning: 'Warning', info: 'Info' }[type] || 'Notification'; }
function getNotificationIcon(type) { return { success: 'ti ti-check', error: 'ti ti-alert-circle', warning: 'ti ti-alert-triangle', info: 'ti ti-info-circle' }[type] || 'ti ti-bell'; }
function showSuccess(message, options = {}) { return showNotification(message, 'success', { duration: 3000, ...options }); }
function showError(message, options = {}) { return showNotification(message, 'error', { duration: 5000, title: 'Error', ...options }); }
function showWarning(message, options = {}) { return showNotification(message, 'warning', { duration: 5000, ...options }); }
function showInfo(message, options = {}) { return showNotification(message, 'info', { duration: 3500, ...options }); }

function getKeywordColor(keyword) {
    let hash = 0;
    for (let i = 0; i < keyword.length; i++) hash = keyword.charCodeAt(i) + ((hash << 5) - hash);
    return `color-${(Math.abs(hash) % 10) + 1}`;
}

function renderInlineKeywordBadges(keywords, maxDisplay = 3) {
    if (!keywords || keywords.length === 0) return '';
    const displayKeywords = keywords.slice(0, maxDisplay);
    const remainingCount = keywords.length - maxDisplay;
    const badges = displayKeywords.map(keyword => {
        const colorClass = getKeywordColor(keyword);
        const displayText = keyword.length > 10 ? keyword.substring(0, 8) + '..' : keyword;
        return `<span class="keyword-badge ${colorClass}" title="Blocked by: ${escapeHtml(keyword)}">${escapeHtml(displayText)}</span>`;
    }).join('');
    let moreBadge = remainingCount > 0 ? `<span class="keyword-badge color-1" title="${remainingCount} more keywords">+${remainingCount}</span>` : '';
    return `<span class="keyword-badges">${badges}${moreBadge}</span>`;
}

async function loadDashboardData() {
    try {
        const stats = await statsManager.loadStats();
        const keywordsResponse = await sendMessageToYouTube({ type: "getKeywords" });
        const keywords = keywordsResponse?.keywords || [];
        updateDashboardUI(stats, keywords);
    } catch (error) {
        console.error('Error loading dashboard data:', error);
        try {
            const stats = await statsManager.loadFromLocalStorage();
            updateDashboardUI(stats, []);
        } catch (fallbackError) {
            updateDashboardUI({ totalBlocks: 0, todayBlocks: 0, manualBlocks: 0, keywordBlocks: 0, shortsBlocks: 0, languageBlocks: 0, activeKeywords: 0, dailyActivity: {} }, []);
        }
    }
}

function updateDashboardUI(stats, keywords) {
    safeElement("#kpi_today", el => el.textContent = stats.todayBlocks.toLocaleString());
    safeElement("#kpi_total", el => el.textContent = stats.totalBlocks.toLocaleString());
    safeElement("#blockingRate", el => el.textContent = statsManager.calculateEfficiency() + '%');
    safeElement("#shortsBlockedKpi", el => el.textContent = stats.shortsBlocks.toLocaleString());
    safeElement("#sponsorBlockKpi", el => el.textContent = (stats.sponsorBlockSkips || 0).toLocaleString());
    safeElement("#manualBlocksKpi", el => el.textContent = stats.manualBlocks.toLocaleString());
    safeElement("#activeKeywords", el => el.textContent = keywords.length.toLocaleString());
    safeElement("#manualBlocksCount", el => el.textContent = stats.manualBlocks.toLocaleString());
    safeElement("#autoBlocksCount", el => el.textContent = stats.keywordBlocks.toLocaleString());
    safeElement("#shortsBlocksCount", el => el.textContent = stats.shortsBlocks.toLocaleString());
    safeElement("#shortsBlocked", el => el.textContent = stats.shortsBlocks.toLocaleString());
    safeElement("#langBlocksCount", el => el.textContent = stats.languageBlocks.toLocaleString());
    safeElement("#channelBlocksCount", el => el.textContent = (stats.channelBlocks || 0).toLocaleString());
    safeElement("#blockedCount", el => el.textContent = stats.totalBlocks.toLocaleString());
    updateActivityChart(stats.dailyActivity);
    updateCapacityDisplay(stats.totalBlocks);
    updateRecentList();
}

async function updateRecentList() {
    try {
        const response = await sendMessageToYouTube({ type: "getBlockedVideos" });
        const blockedVideos = response?.blockedVideosMap || {};
        const videos = Object.values(blockedVideos);
        const recentVideos = videos.sort((a, b) => b.ts - a.ts).slice(0, 10);
        const recentList = $("#recentList");
        if (!recentList) return;
        if (recentVideos.length === 0) {
            recentList.innerHTML = '<div class="recent-item" style="text-align: center; color: var(--text-muted);"><i class="ti ti-inbox" style="font-size: 24px; margin-bottom: 8px;"></i><div>No videos blocked yet</div><div style="font-size: 12px; margin-top: 4px;">Start blocking videos to see them here</div></div>';
        } else {
            recentList.innerHTML = recentVideos.map(video => {
                const hasKeywords = video.matchingKeywords && video.matchingKeywords.length > 0;
                const keywordBadges = hasKeywords ? renderInlineKeywordBadges(video.matchingKeywords, 2) : '';
                return `<div class="recent-item"><div class="recent-info"><div class="title-main-row" style="margin-bottom: 4px;"><div class="recent-title" title="${escapeHtml(video.title)}">${escapeHtml(video.title.length > 35 ? video.title.substring(0, 35) + '...' : video.title)}</div>${keywordBadges}</div><div class="recent-meta">${getReasonBadgeHTML(video.reason, '', 'font-size: 9px; padding: 2px 6px;')}<span style="font-size: 11px;">${formatTimeAgo(video.ts)}</span></div></div></div>`;
            }).join('');
        }
    } catch (error) {
        const recentList = $("#recentList");
        if (recentList) recentList.innerHTML = '<div class="recent-item" style="text-align: center; color: var(--text-muted);"><i class="ti ti-alert-triangle" style="font-size: 24px; margin-bottom: 8px;"></i><div>Failed to load recent videos</div></div>';
    }
}

function updateActivityChart(dailyActivity) {
    const activityBars = $("#activityBars");
    if (!activityBars) return;
    const dates = [];
    for (let i = 29; i >= 0; i--) { const date = new Date(); date.setDate(date.getDate() - i); dates.push(date.toISOString().slice(0, 10)); }
    const maxCount = Math.max(...dates.map(date => dailyActivity[date] || 0), 1);
    activityBars.innerHTML = dates.map(date => {
        const count = dailyActivity[date] || 0;
        const height = maxCount > 0 ? Math.max(6, (count / maxCount) * 100) : 6;
        return `<div class="activity-bar" data-count="${count}" style="height: ${height}%" title="${date}: ${count} blocks"></div>`;
    }).join('');
}

function updateCapacityDisplay(totalBlocks) {
    const capacityElement = $("#capacityDisplay");
    if (!capacityElement) return;
    const maxCapacity = 500000;
    const usagePercent = Math.min(100, Math.round((totalBlocks / maxCapacity) * 100));
    let fillClass = '', message = 'Your storage is looking great! Keep blocking those annoying videos.';
    if (usagePercent >= 95) { fillClass = 'danger'; message = 'Hey! Your storage is completely full. You need to clear some videos to block new ones.'; }
    else if (usagePercent >= 85) { fillClass = 'warning'; message = 'Heads up! Storage getting full (' + usagePercent + '%). ??'; }
    capacityElement.innerHTML = `<div class="capacity-info"><div class="capacity-label">Your Hidden Videos:</div><div class="capacity-value">${totalBlocks} / ${maxCapacity}</div><div class="capacity-bar-container"><div class="capacity-bar"><div class="capacity-fill ${fillClass}" style="width: ${usagePercent}%"></div></div><span class="capacity-percent">${usagePercent}%</span></div><div class="capacity-message">${message}</div></div>`;
}

function initEnhancedSearch() {
    enhancedSearch.initialize();
    setupSearchEventListeners();
    setupAdvancedFilters();
}

function setupSearchEventListeners() {
    const searchInput = $('#search');
    const clearSearch = $('#clearSearch');
    const suggestionsContainer = $('#searchSuggestions');
    if (!searchInput || !suggestionsContainer) return;
    searchInput.addEventListener('input', debounce(async (e) => { const query = e.target.value.trim(); await handleSearch(query); showSearchSuggestions(query); }, 300));
    searchInput.addEventListener('keydown', (e) => {
        switch (e.key) {
            case 'ArrowDown': e.preventDefault(); navigateSuggestions(1); break;
            case 'ArrowUp': e.preventDefault(); navigateSuggestions(-1); break;
            case 'Enter': e.preventDefault(); selectSuggestion(); break;
            case 'Escape': hideSuggestions(); break;
        }
    });
    if (clearSearch) clearSearch.addEventListener('click', () => { searchInput.value = ''; handleSearch(''); hideSuggestions(); searchInput.focus(); });
    document.addEventListener('click', (e) => { if (!e.target.closest('.search-container')) hideSuggestions(); });
}

function setupAdvancedFilters() {
    const advancedToggle = $('#advancedSearchToggle');
    const advancedPanel = $('#advancedSearch');
    if (advancedToggle && advancedPanel) {
        advancedToggle.addEventListener('click', () => {
            advancedPanel.classList.toggle('collapsed');
            advancedToggle.innerHTML = advancedPanel.classList.contains('collapsed') ? '<i class="ti ti-chevron-down"></i>' : '<i class="ti ti-chevron-up"></i>';
        });
    }
    ['#advancedReasonFilter', '#advancedSortFilter', '#advancedDateRangeFilter'].forEach(filterId => {
        const filter = $(filterId);
        if (filter) filter.addEventListener('change', () => { syncAdvancedFilters(); handleSearch($('#search')?.value || ''); });
    });
}

function syncAdvancedFilters() {
    const advancedReason = $('#advancedReasonFilter')?.value;
    const advancedSort = $('#advancedSortFilter')?.value;
    const advancedDate = $('#advancedDateRangeFilter')?.value;
    if (advancedReason) $('#reasonFilter').value = advancedReason;
    if (advancedSort) $('#sortFilter').value = advancedSort;
    if (advancedDate) $('#dateRangeFilter').value = advancedDate;
}

function setupFooterCollapsibles() {
    document.querySelectorAll('.ftt-toggle').forEach(btn => {
        btn.addEventListener('click', () => {
            btn.closest('.ftt-collapsible').classList.toggle('open');
        });
    });
    document.querySelectorAll('.ftt-toggle-sub').forEach(btn => {
        btn.addEventListener('click', () => {
            btn.closest('.ftt-donate-region').classList.toggle('open');
        });
    });
    document.querySelectorAll('.ftt-copyable').forEach(el => {
        el.addEventListener('click', () => {
            const text = el.getAttribute('data-copy');
            if (text) {
                navigator.clipboard.writeText(text).then(() => {
                    const icon = el.querySelector('i');
                    if (icon) { icon.className = 'ti ti-check'; setTimeout(() => icon.className = 'ti ti-copy', 1500); }
                });
            }
        });
    });
}

function setupQuickFilters() {
    $$('.quick-filter').forEach(filter => {
        filter.addEventListener('click', function () {
            const filterType = this.getAttribute('data-filter');
            const filterValue = this.getAttribute('data-value');
            $$('.quick-filter').forEach(f => f.classList.remove('active'));
            this.classList.add('active');
            applyQuickFilter(filterType, filterValue);
        });
    });
}

function applyQuickFilter(type, value) {
    const searchInput = $('#search');
    switch (type) {
        case 'reason': $('#reasonFilter').value = value; if (searchInput) { searchInput.value = value; handleSearch(value); } break;
        case 'date': $('#dateRangeFilter').value = 'today'; if (searchInput) { searchInput.value = 'today'; handleSearch('today'); } break;
    }
}

async function handleSearch(query = '') {
    const startTime = performance.now();
    try {
        const filters = { reason: $('#reasonFilter')?.value || 'all', sortBy: $('#sortFilter')?.value || 'newest', dateRange: $('#dateRangeFilter')?.value || 'all' };
        const results = await enhancedSearch.search(query, filters);
        updateSearchResults(results, query);
        updateResultsInfo(results.length, query, performance.now() - startTime);
    } catch (error) { console.error('Search error:', error); showError('Search failed. Please try again.'); }
}

function updateSearchResults(results, query) {
    const tableBody = $("#videosTableBody");
    const emptyState = $("#emptyState");
    const loadingState = $("#loadingState");
    if (loadingState) loadingState.classList.remove('show');
    if (!tableBody) return;
    if (results.length === 0) {
        if (emptyState) emptyState.classList.add('show');
        tableBody.innerHTML = `<tr><td colspan="5" style="text-align: center; padding: 40px; color: var(--text-muted);"><i class="ti ti-search" style="font-size: 32px; margin-bottom: 16px; opacity: 0.5;"></i><div style="font-size: 16px; font-weight: 600; margin-bottom: 8px;">No videos found</div><div style="font-size: 14px;">${query ? `No results for "${escapeHtml(query)}"` : 'No blocked videos yet'}</div></td></tr>`;
        pagination.update(0);
    } else {
        if (emptyState) emptyState.classList.remove('show');
        const currentPage = pagination.getCurrentPage();
        const size = pagination.getPageSize();
        const start = (currentPage - 1) * size;
        const paged = results.slice(start, start + size);
        pagination.update(results.length, currentPage);
        tableBody.innerHTML = paged.map(video => {
            const hasKeywords = video.matchingKeywords && video.matchingKeywords.length > 0;
            const keywordBadges = hasKeywords ? renderInlineKeywordBadges(video.matchingKeywords) : '';
            return `<tr data-block-reason="${video.reason}">
                <td class="col-title"><div class="title-with-badges"><div class="title-main-row"><span class="video-title-text">${highlightText(video.title, query)}</span>${keywordBadges}</div>${hasKeywords ? `<div class="keyword-summary"><i class="ti ti-filter"></i> Blocked by ${video.keywordCount} keyword${video.keywordCount !== 1 ? 's' : ''}</div>` : ''}</div></td>
                <td class="col-id">${highlightText(video.videoId, query)}</td>
                <td class="col-reason">${getReasonBadgeHTML(video.reason)}</td>
                <td class="col-date"><div class="date-time-display"><div class="full-date">${formatLocalDateTime(video.ts)}</div><div class="relative-time">${formatTimeAgo(video.ts)}</div></div></td>
                <td class="col-actions"><button class="control-btn small unblock-btn" data-video-id="${video.videoId}" title="Unblock video"><i class="ti ti-rotate"></i></button></td>
            </tr>`;
        }).join('');
        attachUnblockListeners();
        attachKeywordBadgeListeners();
    }
}

function highlightText(text, query) {
    if (!query || !text) return escapeHtml(text);
    if (!text.toLowerCase().includes(query.toLowerCase())) return escapeHtml(text);
    const regex = new RegExp(`(${escapeRegex(query)})`, 'gi');
    return escapeHtml(text).replace(regex, '<mark class="search-highlight">$1</mark>');
}

function escapeRegex(string) { return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

function showSearchSuggestions(query) {
    const suggestionsContainer = $('#searchSuggestions');
    if (!suggestionsContainer) return;
    if (!query || query.length < 2) { hideSuggestions(); return; }
    const suggestions = enhancedSearch.getSearchSuggestions(query);
    if (suggestions.length === 0) { hideSuggestions(); return; }
    suggestionsContainer.innerHTML = suggestions.map(s => `<div class="suggestion-item" data-suggestion="${escapeHtml(s)}">${highlightText(s, query)}</div>`).join('');
    suggestionsContainer.classList.add('show');
    $$('.suggestion-item', suggestionsContainer).forEach(item => {
        item.addEventListener('click', function () { const s = this.getAttribute('data-suggestion'); $('#search').value = s; handleSearch(s); hideSuggestions(); });
    });
}

function hideSuggestions() { const c = $('#searchSuggestions'); if (c) c.classList.remove('show'); }
function navigateSuggestions(direction) {
    const suggestions = $$('.suggestion-item');
    const active = $('.suggestion-item.active');
    let nextIndex = 0;
    if (active) { const currentIndex = suggestions.indexOf(active); nextIndex = (currentIndex + direction + suggestions.length) % suggestions.length; active.classList.remove('active'); }
    suggestions[nextIndex]?.classList.add('active');
}
function selectSuggestion() { const active = $('.suggestion-item.active'); if (active) { const s = active.getAttribute('data-suggestion'); $('#search').value = s; handleSearch(s); hideSuggestions(); } }

function updateResultsInfo(count, query, duration) {
    const resultsInfo = $('#resultsInfo');
    if (!resultsInfo) return;
    let infoText = `<span class="results-count">${count}</span> videos`;
    if (query) infoText += ` for "${escapeHtml(query)}"`;
    infoText += ` � ${duration.toFixed(0)}ms`;
    resultsInfo.innerHTML = infoText;
}

function attachUnblockListeners() {
    $$('.unblock-btn').forEach(btn => {
        btn.addEventListener('click', async function () {
            const videoId = this.getAttribute('data-video-id');
            if (confirm('Are you sure you want to unblock this video?')) {
                try { await sendMessageToYouTube({ type: "unblockVideo", videoId }); showSuccess("Video unblocked!"); await enhancedSearch.refreshIndex(); handleSearch($('#search')?.value || ''); loadDashboardData(); }
                catch (error) { showError("Failed to unblock video"); }
            }
        });
    });
}

function attachKeywordBadgeListeners() {
    $$('.keyword-badge').forEach(badge => {
        badge.addEventListener('click', function (e) {
            e.stopPropagation();
            const keyword = this.textContent.replace(/^\+(.+)/, '');
            if (keyword && !keyword.startsWith('+')) { const searchInput = $('#search'); if (searchInput) { searchInput.value = keyword; handleSearch(keyword); } }
        });
        badge.style.cursor = 'pointer';
    });
}

async function renderBlockedTable(page, pageSize) {
    const tableBody = $("#videosTableBody");
    const loadingState = $("#loadingState");
    const emptyState = $("#emptyState");
    if (!tableBody) return;
    if (loadingState) loadingState.classList.add('show');
    if (emptyState) emptyState.classList.remove('show');
    tableBody.innerHTML = '';
    try {
        const response = await sendMessageToYouTube({ type: "getBlockedVideos" });
        const blockedVideos = response?.blockedVideosMap || {};
        const videos = Object.values(blockedVideos);
        if (videos.length === 0) { if (emptyState) emptyState.classList.add('show'); pagination.update(0); }
        else {
            videos.sort((a, b) => b.ts - a.ts);
            const currentPage = page || pagination.getCurrentPage();
            const size = pageSize || pagination.getPageSize();
            const start = (currentPage - 1) * size;
            const paged = videos.slice(start, start + size);
            pagination.update(videos.length, currentPage);
            tableBody.innerHTML = paged.map(video => {
                const hasKeywords = video.matchingKeywords && video.matchingKeywords.length > 0;
                const keywordBadges = hasKeywords ? renderInlineKeywordBadges(video.matchingKeywords) : '';
                return `<tr data-block-reason="${video.reason}">
                    <td class="col-title"><div class="title-with-badges"><div class="title-main-row"><span class="video-title-text">${escapeHtml(video.title)}</span>${keywordBadges}</div>${hasKeywords ? `<div class="keyword-summary"><i class="ti ti-filter"></i> Blocked by ${video.keywordCount} keyword${video.keywordCount !== 1 ? 's' : ''}</div>` : ''}</div></td>
                    <td class="col-id">${video.id}</td>
                    <td class="col-reason">${getReasonBadgeHTML(video.reason)}</td>
                    <td class="col-date"><div class="date-time-display"><div class="full-date">${formatLocalDateTime(video.ts)}</div><div class="relative-time">${formatTimeAgo(video.ts)}</div></div></td>
                    <td class="col-actions"><button class="control-btn small unblock-btn" data-video-id="${video.id}" title="Unblock video"><i class="ti ti-rotate"></i></button></td>
                </tr>`;
            }).join('');
            attachUnblockListeners();
            attachKeywordBadgeListeners();
        }
        safeElement("#resultsCount", el => { el.textContent = videos.length; });
    } catch (error) { showError("Failed to load blocked videos"); }
    finally { if (loadingState) loadingState.classList.remove('show'); }
}

function debounce(func, wait, immediate) {
    let timeout;
    return function (...args) {
        const later = () => { timeout = null; if (!immediate) func(...args); };
        const callNow = immediate && !timeout;
        clearTimeout(timeout);
        timeout = setTimeout(later, wait);
        if (callNow) func(...args);
    };
}

// Native Ad Blocker Panel
function initAdBlockerPanel() {
    loadAdBlockerConfig();
    loadAdBlockerStats();

    ['#toggleVideoAds', '#toggleDisplayAds', '#toggleAutoSkip', '#toggleTrackerBlock', '#toggleAnnotationBlock', '#toggleSurveyBlock'].forEach(id => {
        safeElement(id, el => {
            el.addEventListener('change', function () { saveAdBlockerConfig(); });
        });
    });

    safeElement('#toggleAdBlocker', el => {
        el.addEventListener('change', function () {
            const enabled = this.checked;
            sendMessageToYouTube({ type: "toggleAdBlocker", enabled, config: {
                videoAds: safeElement('#toggleVideoAds')?.checked !== false,
                displayAds: safeElement('#toggleDisplayAds')?.checked !== false,
                autoSkip: safeElement('#toggleAutoSkip')?.checked !== false,
                trackers: safeElement('#toggleTrackerBlock')?.checked !== false,
                annotations: safeElement('#toggleAnnotationBlock')?.checked !== false,
                surveys: safeElement('#toggleSurveyBlock')?.checked !== false
            }}).then(() => {
                loadAdBlockerStats();
                showSuccess(enabled ? "Ad blocker enabled" : "Ad blocker disabled");
            });
        });
    });

    safeElement('#saveAdBlockerSettings', el => {
        el.addEventListener('click', function () { saveAdBlockerConfig(); });
    });

    safeElement('#howItWorksTrigger', el => {
        el.addEventListener('click', function (e) {
            e.stopPropagation();
            const popover = $('#howItWorksPopover');
            if (popover) popover.classList.toggle('open');
        });
    });
    document.addEventListener('click', function (e) {
        const popover = $('#howItWorksPopover');
        const trigger = $('#howItWorksTrigger');
        if (popover && trigger && !popover.contains(e.target) && !trigger.contains(e.target)) {
            popover.classList.remove('open');
        }
    });
}

async function loadAdBlockerConfig() {
    try {
        const response = await sendMessageToYouTube({ type: "getAdBlockerStatus" });
        const config = response?.config || {};
        const adBlockerEnabled = config.adBlocker !== false;
        safeElement('#toggleAdBlocker', el => el.checked = adBlockerEnabled);
        safeElement('#toggleVideoAds', el => el.checked = config.videoAds !== false);
        safeElement('#toggleDisplayAds', el => el.checked = config.displayAds !== false);
        safeElement('#toggleAutoSkip', el => el.checked = config.autoSkip !== false);
        safeElement('#toggleTrackerBlock', el => el.checked = config.trackers !== false);
        safeElement('#toggleAnnotationBlock', el => el.checked = config.annotations !== false);
        safeElement('#toggleSurveyBlock', el => el.checked = config.surveys !== false);
    } catch (error) {
        console.error('Error loading ad blocker config:', error);
    }
}

async function loadAdBlockerStats() {
    try {
        let adsBlocked = 0, bannersRemoved = 0, skipped = 0, ruleCount = 0, config = {};
        try {
            const result = await new Promise((resolve) => {
                chrome.storage.local.get(['adBlockerConfig', 'clify_data'], (r) => resolve(r));
            });
            config = result.adBlockerConfig || {};
            const clifyData = result.clify_data || {};
            const stats = clifyData.stats || {};
            adsBlocked = stats.adsBlocked || 0;
            bannersRemoved = stats.bannersRemoved || 0;
            skipped = stats.skipped || 0;
        } catch (e) {}
        try {
            const rules = await chrome.declarativeNetRequest.getDynamicRules();
            ruleCount = rules.length;
        } catch (e) {}
        try {
            const response = await sendMessageToYouTube({ type: "getAdBlockerStatus" });
            if (response?.success) {
                if (response.stats) {
                    adsBlocked = response.stats.totalBlocked || adsBlocked;
                    bannersRemoved = response.stats.bannersRemoved || bannersRemoved;
                    skipped = response.stats.skipped || skipped;
                }
                if (response.ruleCount) ruleCount = response.ruleCount;
                if (response.config && Object.keys(response.config).length > 0) config = response.config;
            }
        } catch (e) {}
        safeElement('#adBlockerAdsBlocked', el => el.textContent = adsBlocked.toLocaleString());
        safeElement('#adBlockerBannerRemoved', el => el.textContent = bannersRemoved.toLocaleString());
        safeElement('#adBlockerSkipped', el => el.textContent = skipped.toLocaleString());
        safeElement('#adBlockerRules', el => el.textContent = ruleCount.toString());
        safeElement('#adsBlockedCount', el => el.textContent = adsBlocked.toLocaleString());
        safeElement('#adBlockerBadge', el => {
            const enabled = config.adBlocker !== false;
            el.innerHTML = enabled ? '<i class="ti ti-shield"></i> Ad Blocker ON' : '<i class="ti ti-shield"></i> Ad Blocker OFF';
            el.style.background = enabled ? 'linear-gradient(135deg, #4caf50, #388e3c)' : 'linear-gradient(135deg, #ff6b6b, #d63031)';
        });
    } catch (error) { console.error('Error loading ad blocker stats:', error); }
}

async function saveAdBlockerConfig() {
    const config = {
        adBlocker: safeElement('#toggleAdBlocker')?.checked !== false,
        videoAds: safeElement('#toggleVideoAds')?.checked !== false,
        displayAds: safeElement('#toggleDisplayAds')?.checked !== false,
        autoSkip: safeElement('#toggleAutoSkip')?.checked !== false,
        trackers: safeElement('#toggleTrackerBlock')?.checked !== false,
        annotations: safeElement('#toggleAnnotationBlock')?.checked !== false,
        surveys: safeElement('#toggleSurveyBlock')?.checked !== false
    };
    chrome.storage.local.set({ adBlockerConfig: config });
    try {
        await sendMessageToYouTube({ type: "toggleAdBlocker", enabled: config.adBlocker, config });
        showSuccess("Ad blocker settings saved!");
    } catch (error) { showError("Failed to save ad blocker settings"); }
}

// Channel Manager
function initChannelManager() {
    loadBlockedChannels();
    loadWhitelistedChannels();

    safeElement('#addChannelBtn', el => {
        el.addEventListener('click', addBlockedChannel);
    });

    safeElement('#addChannelInput', el => {
        el.addEventListener('keydown', (e) => { if (e.key === 'Enter') addBlockedChannel(); });
    });

    safeElement('#addWhitelistBtn', el => {
        el.addEventListener('click', addWhitelistedChannel);
    });

    safeElement('#addWhitelistInput', el => {
        el.addEventListener('keydown', (e) => { if (e.key === 'Enter') addWhitelistedChannel(); });
    });

    safeElement('#clearAllChannels', el => {
        el.addEventListener('click', async () => {
            if (!confirm('Are you sure you want to clear all blocked channels?')) return;
            try {
                await sendMessageToYouTube({ type: "clearAllChannels" });
                loadBlockedChannels();
                showSuccess("All blocked channels cleared!");
            } catch (error) { showError("Failed to clear channels"); }
        });
    });
}

async function loadBlockedChannels() {
    try {
        const response = await sendMessageToYouTube({ type: "getBlockedChannels" });
        const raw = response?.channels || response?.blockedChannels || [];
        const channels = Array.isArray(raw) ? raw : Object.values(raw);
        renderChannelList(channels, '#blockedChannelsList', 'blocked');
        const countEl = document.getElementById('blockedChannelsCount');
        if (countEl) countEl.textContent = channels.length;
        const badgeEl = document.getElementById('blockedChannelsCountBadge');
        if (badgeEl) badgeEl.textContent = channels.length;
    } catch (error) { console.error('Error loading blocked channels:', error); }
}

async function loadWhitelistedChannels() {
    try {
        const response = await sendMessageToYouTube({ type: "getWhitelistedChannels" });
        const raw = response?.channels || response?.whitelistedChannels || [];
        const channels = Array.isArray(raw) ? raw : Object.values(raw);
        renderChannelList(channels, '#whitelistedChannelsList', 'whitelisted');
        const countEl = document.getElementById('whitelistedChannelsCount');
        if (countEl) countEl.textContent = channels.length;
        const badgeEl = document.getElementById('whitelistedChannelsCountBadge');
        if (badgeEl) badgeEl.textContent = channels.length;
    } catch (error) { console.error('Error loading whitelisted channels:', error); }
}

function renderChannelList(channels, containerId, type) {
    const container = $(containerId);
    if (!container) return;
    if (channels.length === 0) {
        container.innerHTML = '';
    } else {
        container.innerHTML = channels.map(ch => {
            const initial = (ch.name || ch.id || '?').charAt(0).toUpperCase();
            return `
            <div class="chm-channel">
                <div class="chm-channel-info">
                    <div class="chm-channel-avatar">${escapeHtml(initial)}</div>
                    <span class="chm-channel-name">${escapeHtml(ch.name || ch.id)}</span>
                </div>
                <button class="chm-channel-remove" data-id="${escapeHtml(ch.id || ch.name)}" data-name="${escapeHtml(ch.name || ch.id)}" data-url="${escapeHtml(ch.url || '')}" data-type="${type}" title="Remove">
                    <i class="ti ti-x"></i>
                </button>
            </div>`;
        }).join('');
        container.querySelectorAll('.chm-channel-remove').forEach(btn => {
            btn.addEventListener('click', function () {
                const id = this.getAttribute('data-id');
                const name = this.getAttribute('data-name');
                const url = this.getAttribute('data-url');
                const chType = this.getAttribute('data-type');
                removeChannel(id || name, url, chType);
            });
        });
    }
}

function extractChannelIdFromInput(value) {
    const urlPatterns = [
        { regex: /youtube\.com\/channel\/(UC[a-zA-Z0-9_-]{22})/, prefix: '' },
        { regex: /youtube\.com\/@([a-zA-Z0-9_.-]+)/, prefix: '@' },
        { regex: /youtube\.com\/c\/([a-zA-Z0-9_-]+)/, prefix: 'c/' },
        { regex: /youtube\.com\/user\/([a-zA-Z0-9_-]+)/, prefix: 'u/' },
        { regex: /youtu\.be\/@([a-zA-Z0-9_.-]+)/, prefix: '@' }
    ];
    for (const { regex, prefix } of urlPatterns) {
        const m = value.match(regex);
        if (m) return { id: prefix + m[1], name: m[1].replace(/[._-]/g, ' ').trim() };
    }
    const clean = value.replace(/^@/, '').trim();
    return { id: '@' + clean, name: clean };
}

async function addBlockedChannel() {
    const input = $('#addChannelInput');
    if (!input || !input.value.trim()) { showError("Please enter a channel name or URL"); return; }
    const value = input.value.trim();
    const { id, name } = extractChannelIdFromInput(value);
    try {
        await sendMessageToYouTube({ type: "blockChannel", channelData: { id, name, url: value } });
        input.value = '';
        showSuccess(`Channel "${name}" blocked!`);
        loadBlockedChannels();
    } catch (error) { showError("Failed to block channel"); }
}

async function addWhitelistedChannel() {
    const input = $('#addWhitelistInput');
    if (!input || !input.value.trim()) { showError("Please enter a channel name or URL"); return; }
    const value = input.value.trim();
    const { id, name } = extractChannelIdFromInput(value);
    try {
        await sendMessageToYouTube({ type: "whitelistChannel", channelData: { id, name, url: value } });
        input.value = '';
        showSuccess(`Channel "${channelName}" whitelisted!`);
        loadWhitelistedChannels();
    } catch (error) { showError("Failed to whitelist channel"); }
}

async function removeChannel(name, url, type) {
    try {
        await sendMessageToYouTube({ type: type === 'blocked' ? 'unblockChannel' : 'unwhitelistChannel', name, url });
        showSuccess(`Channel "${name}" removed!`);
        if (type === 'blocked') loadBlockedChannels(); else loadWhitelistedChannels();
    } catch (error) { showError("Failed to remove channel"); }
}

